<script lang="ts">import { apiFetch } from '$lib/api/client'; import type { InventoryResponse } from '$lib/api/types'; import InventoryLedger from '$lib/components/inventory/InventoryLedger.svelte'; import ConfidenceNotice from '$lib/components/inventory/ConfidenceNotice.svelte'; let data=$state<InventoryResponse>({items:[],warnings:[],total_quantity:0});let query=$state('');let color=$state('');let timer:ReturnType<typeof setTimeout>;async function load(){const params=new URLSearchParams();if(query)params.set('q',query);if(color)params.set('color_id',color);data=await apiFetch<InventoryResponse>(`/api/inventory?${params}`);}function search(){clearTimeout(timer);timer=setTimeout(()=>void load(),180)}$effect(()=>{void load();});let unique=$derived(new Set(data.items.map((item)=>item.part_num)).size);let colors=$derived([...new Map(data.items.map((item)=>[item.color_id,item.color_name])).entries()]);</script>
<svelte:head><title>Inventory · What2Build</title></svelte:head><section class="page-head"><div><p class="eyebrow">Inventory ledger</p><h1>Available pieces</h1><p>{data.total_quantity} total parts · {unique} unique parts</p></div><div class="filters"><label>Search <input placeholder="Part number or name" bind:value={query} oninput={search}/></label><label>Color <select bind:value={color} onchange={()=>void load()}><option value="">All colors</option>{#each colors as [id,name]}<option value={id}>{name}</option>{/each}</select></label></div></section><ConfidenceNotice warnings={data.warnings}/><InventoryLedger items={data.items}/>
<style>.page-head{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:20px}.eyebrow{margin:0;color:var(--blue);font-size:.72rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.page-head h1{margin:3px 0;font-size:2rem;letter-spacing:-.04em}.page-head p:not(.eyebrow){margin:0;color:var(--ink-muted)}.filters{display:flex;gap:8px;flex-wrap:wrap}.filters label{display:grid;gap:4px;color:var(--ink-muted);font-size:.72rem;font-weight:800;text-transform:uppercase}.filters input,.filters select{min-height:35px;padding:6px;border:1px solid var(--line);background:var(--surface);color:var(--ink);font-size:.85rem;text-transform:none}@media(max-width:719px){.page-head{align-items:start;flex-direction:column}.filters{width:100%}.filters label:first-child{flex:1}.filters input{width:100%}}</style>
